create or replace function public.nino_diagnosis_context_for_user(_user_id uuid) returns jsonb language plpgsql stable security definer set search_path=public as $$
declare v public.nino_diagnosis_snapshots; begin if _user_id is null then return jsonb_build_object('ok',false,'error','missing_user'); end if; select * into v from public.nino_diagnosis_snapshots where user_id=_user_id and run_mode='live' and is_current order by created_at desc limit 1; if v.id is null then return jsonb_build_object('ok',true,'contract','nino_diagnosis_contract.v1.1','snapshot_id',null,'as_of',now(),'overall_state','insufficient_data','primary_situation',null,'primary_action',null,'supporting_situations','[]'::jsonb,'patterns','[]'::jsonb,'anticipations','[]'::jsonb,'operational_tasks','[]'::jsonb,'timeline','[]'::jsonb,'closings','[]'::jsonb,'narrative','{}'::jsonb,'forecast','{}'::jsonb,'data_quality','{}'::jsonb,'confidence',0,'rationale','{}'::jsonb,'snapshot_payload','{}'::jsonb); end if; return jsonb_build_object('ok',true,'contract',v.contract_version,'snapshot_id',v.id,'as_of',v.created_at,'overall_state',v.overall_state,'primary_situation',(select to_jsonb(s) from public.financial_situations s where s.id=v.primary_situation_id),'primary_action',(select to_jsonb(a) from public.financial_situation_actions a where a.id=v.primary_action_id),'supporting_situations',coalesce((select jsonb_agg(to_jsonb(s) order by array_position(v.supporting_situation_ids,s.id)) from public.financial_situations s where s.id=any(v.supporting_situation_ids)),'[]'::jsonb),'patterns',coalesce((select jsonb_agg(to_jsonb(s) order by relevance_score desc) from public.financial_situations s where user_id=_user_id and run_mode='live' and situation_type='behavioral_pattern' and status in ('observed','confirmed','active')),'[]'::jsonb),'anticipations',coalesce((select jsonb_agg(to_jsonb(s) order by period_end) from public.financial_situations s where user_id=_user_id and run_mode='live' and temporal_scope='future' and status in ('active','confirmed')),'[]'::jsonb),'operational_tasks',coalesce((select jsonb_agg(to_jsonb(s) order by relevance_score desc) from public.financial_situations s where user_id=_user_id and run_mode='live' and narrative_role='operational' and status in ('observed','active','confirmed')),'[]'::jsonb),'timeline',coalesce((select jsonb_agg(x order by x->>'last_event_at' desc) from (select jsonb_build_object('situation_id',s.id,'situation_key',s.situation_key,'headline',s.headline,'last_event_at',max(e.occurred_at),'events',jsonb_agg(to_jsonb(e) order by e.occurred_at desc)) x from public.financial_situations s join public.financial_situation_events e on e.situation_id=s.id where s.user_id=_user_id group by s.id order by max(e.occurred_at) desc limit 20) q),'[]'::jsonb),'closings',coalesce((select jsonb_agg(jsonb_build_object('id',id,'report_type',report_type,'period_start',period_start,'period_end',period_end,'summary',summary,'closing_text',closing_text,'created_at',created_at) order by period_end desc) from public.financial_reports where user_id=_user_id and status in ('generated','published')),'[]'::jsonb),'narrative',coalesce(v.payload->'narrative','{}'::jsonb),'forecast',v.forecast,'data_quality',v.data_quality,'confidence',v.confidence,'rationale',v.rationale,'snapshot_payload',v.payload); end $$;